(82,'ورقة عمل (58) أنا والطقس','ماذا أختار عند المطر في الخارج؟','مظلة مناسبة','ورقة غير محمية','كتابًا فوق رأسي بدل المظلة','قبعة ورقية غير مقاومة للماء',''),
(83,'ورقة عمل (59) ألاحظ وأتحدث','كيف أصف شيئًا ألاحظه؟','أقول لونًا وشكلًا أراه فعلًا','أختلق تفاصيل لا أراها','أسخر من وصف زميلي','أرفض ملاحظة الأشياء',''),
(84,'مفكرة التعلم','ما الجملة التي تساعدني على متابعة تعلّمي؟','تعلمت اليوم حرفًا جديدًا وأريد تدريبه','لا أهتم بما تعلمت','لن أراجع إجابتي','كل الدروس متشابهة دائمًا','نشاط انعكاس تعلّم مستقل عن كتاب الوزارة.'),
(85,'قاموسي المصور','أي كلمة تدل على شيء نقرأه؟','كتاب','ملعقة','حذاء','كرة','نشاط مفردات أصلي بحسب عنوان القاموس المصور، وليس وصف صور الكتاب.'),
(86,'التقويم النهائي للوحدة','ما الخطوة المناسبة عندما لا أعرف إجابة سؤال التقويم؟','أراجع المثال وأطلب توضيحًا','أترك التعلم نهائيًا','أخمن دائمًا دون مراجعة','أنسخ دون فهم','')
), scoped AS (
 SELECT l.id,qa.* FROM qa JOIN public.lessons l ON l.title=qa.title
  AND l.sort_order=qa.sort_order AND l.status='published'
 JOIN public.units u ON u.id=l.unit_id AND u.title='نتهيأ للمدرسة — الأنشطة والتهيئة' AND u.semester=1
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=1 AND g.name_ar='الصف الأول'
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
 WHERE length(coalesce(l.content,''))>350 AND l.content LIKE '%ضاديوم%'
)
INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'تهيئة وتطبيق من تأليف ضاديوم','multiple_choice','assessment',s.prompt,
 jsonb_build_object('origin','DADYOOM_BH_G1_T1_READINESS_85_ORIGINAL_TITLE_BASED_20261008','alignmentStatus','TITLE_BASED_ORIGINAL_ONLY_NEEDS_BOOK_OCR_REVIEW','bookTextCopied',false,
  'reviewStatus','required','text','تدريب ضاديوم من عنوان الورقة ولا يثبت صحة النص المستخرج من ملف مصدر.',
  'teacherNote',coalesce(nullif(s.note,''),'يحتاج المعلم مراجعة المطابقة مع الورقة الأصلية.'),'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),
 jsonb_build_object('correct',s.correct),1,5,true,true
FROM scoped s WHERE NOT EXISTS(
 SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G1_T1_READINESS_85_ORIGINAL_TITLE_BASED_20261008'
);
-- Transparently label OCR/misaligned legacy content without deleting or altering its original body.
UPDATE public.lessons l
 SET content='تنبيه تحرير ضاديوم: وصف هذه الورقة في السجل السابق قد يحتوي على نتائج استخراج نصي غير مطابقة لعنوانها. النشاط التفاعلي المرفق تدريب أصلي مبني على العنوان فقط؛ راجع ورقة العمل الرسمية مع المعلم قبل اعتبار المصدر مطابقًا.

' || l.content, updated_at=now()
FROM public.units u JOIN public.grades g ON g.id=u.grade_id
JOIN public.curricula cu ON cu.id=g.curriculum_id
JOIN public.countries c ON c.id=cu.country_id
WHERE l.unit_id=u.id AND u.title='نتهيأ للمدرسة — الأنشطة والتهيئة' AND u.semester=1
 AND g.grade_number=1 AND g.name_ar='الصف الأول'
 AND cu.academic_year='2026-2027' AND c.code='BH' AND l.status='published'
 AND EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.content->>'origin'='DADYOOM_BH_G1_T1_READINESS_85_ORIGINAL_TITLE_BASED_20261008')
 AND left(l.content,19)<>'تنبيه تحرير ضاديوم:';
